import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"Кэширование","description":"","frontmatter":{},"headers":[],"relativePath":"ru/advanced/caching.md","filePath":"ru/advanced/caching.md","lastUpdated":1784903584000}'),c={name:"ru/advanced/caching.md"};function i(d,a,o,l,p,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="кэширование" tabindex="-1">Кэширование <a class="header-anchor" href="#кэширование" aria-label="Permalink to &quot;Кэширование&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>swag2mcp кэширует скачанные файлы спецификаций, чтобы MCP-сервер запускался быстрее при последующих запусках. Вместо загрузки одного и того же файла спецификации каждый раз используется кэшированная копия.</p><h2 id="как-работает-кэширование" tabindex="-1">Как работает кэширование <a class="header-anchor" href="#как-работает-кэширование" aria-label="Permalink to &quot;Как работает кэширование&quot;">​</a></h2><p>Когда вы добавляете спецификацию с удалённым URL, swag2mcp скачивает её и сохраняет в директорию <code>cache/</code>. При следующем запуске он проверяет, актуальна ли кэшированная копия. Если да, загрузка пропускается.</p><h3 id="что-кэшируется" tabindex="-1">Что кэшируется <a class="header-anchor" href="#что-кэшируется" aria-label="Permalink to &quot;Что кэшируется&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Источник</th><th>Поведение</th></tr></thead><tbody><tr><td><strong>Удалённый URL</strong> (http/https)</td><td>Всегда кэшируется. Скачивается один раз, используется повторно до истечения кэша.</td></tr><tr><td><strong>Локальный файл в <code>specs/</code></strong></td><td>Используется напрямую из директории <code>specs/</code>. Никогда не кэшируется — изменения видны сразу.</td></tr><tr><td><strong>Локальный файл вне <code>specs/</code></strong></td><td>Копируется в кэш. Если исходный файл изменяется (время модификации), кэш аннулируется.</td></tr></tbody></table><h3 id="истечение-кэша-ttl" tabindex="-1">Истечение кэша (TTL) <a class="header-anchor" href="#истечение-кэша-ttl" aria-label="Permalink to &quot;Истечение кэша (TTL)&quot;">​</a></h3><p>Каждый кэшированный файл получает случайное время истечения от <strong>1 часа до 48 часов</strong>. Случайность предотвращает одновременное истечение всех кэшированных файлов (что вызвало бы &quot;толпящееся стадо&quot; загрузок).</p><ul><li>TTL сбрасывается каждый раз при запуске MCP-сервера</li><li>Если кэшированный файл всё ещё в пределах TTL, он используется повторно</li><li>Если TTL истёк, файл загружается снова</li></ul><h3 id="структура-кэша" tabindex="-1">Структура кэша <a class="header-anchor" href="#структура-кэша" aria-label="Permalink to &quot;Структура кэша&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # Кэшированный файл спецификации</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # Метаданные (источник, TTL, время кэширования)</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>Ключ кэша формируется из URL или пути файла спецификации. Каждый кэшированный файл имеет сопутствующий файл <code>.meta</code>, в котором хранится время кэширования и истечения.</p><h2 id="управление-кэшем" tabindex="-1">Управление кэшем <a class="header-anchor" href="#управление-кэшем" aria-label="Permalink to &quot;Управление кэшем&quot;">​</a></h2><h3 id="принудительное-обновление" tabindex="-1">Принудительное обновление <a class="header-anchor" href="#принудительное-обновление" aria-label="Permalink to &quot;Принудительное обновление&quot;">​</a></h3><p>Выполните <code>swag2mcp update</code>, чтобы очистить весь кэш и перезагрузить все файлы спецификаций:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Это проверяет конфиг, очищает кэш и загружает всё заново.</p><h3 id="ручная-очистка-кэша" tabindex="-1">Ручная очистка кэша <a class="header-anchor" href="#ручная-очистка-кэша" aria-label="Permalink to &quot;Ручная очистка кэша&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>Это удаляет все кэшированные файлы спецификаций и сохранённые ответы API. При следующем запуске MCP-сервера все спецификации будут загружены снова.</p><h3 id="автоматическая-очистка" tabindex="-1">Автоматическая очистка <a class="header-anchor" href="#автоматическая-очистка" aria-label="Permalink to &quot;Автоматическая очистка&quot;">​</a></h3><p>При запуске MCP-сервера (<code>swag2mcp mcp</code>) сохранённые ответы API старше 48 часов автоматически удаляются. Это предотвращает бесконечный рост директории <code>responses/</code>.</p><h2 id="важные-замечания" tabindex="-1">Важные замечания <a class="header-anchor" href="#важные-замечания" aria-label="Permalink to &quot;Важные замечания&quot;">​</a></h2><ul><li><strong>Локальные файлы в <code>specs/</code> никогда не кэшируются</strong> — если вы редактируете файл спецификации напрямую в директории <code>specs/</code>, изменения видны сразу без очистки кэша</li><li><strong>Удалённые URL всегда кэшируются</strong> — нет способа обойти кэш для удалённых URL, кроме выполнения <code>swag2mcp update</code> или <code>swag2mcp clean</code></li><li><strong>Кэш локальный</strong> — он хранится на диске и не синхронизируется между машинами. Используйте <code>swag2mcp export</code> и <code>swag2mcp import</code> для переноса спецификаций между машинами</li></ul>`,25)])])}const u=e(c,[["render",i]]);export{b as __pageData,u as default};
